module sanitaire(input clk, input rst_n, input start, input [7:0] enclosure_count, input [7:0] animal_count, input [7:0] correct_animal [0:3], input [7:0] num_animals [0:3], input [7:0] animal_types [0:7], input [7:0] enclosure_idx [0:7], output reg [1:0] result, output reg done); reg [2:0] state; reg [3:0] incorrect_enc; reg [15:0] adj_matrix; reg [1:0] result_reg; reg done_reg; always @(posedge clk) begin if (!rst_n) begin state <= 0; incorrect_enc <= 0; adj_matrix <= 0; result_reg <= 0; done_reg <= 0; end else begin case (state) 0: begin if (start) state <= 1; else state <= 0; done_reg <= 0; result_reg <= 0; end 1: begin incorrect_enc <= 0; adj_matrix <= 0; if (enclosure_count > 0 && animal_count > 0 && enclosure_idx[0] != 0) begin incorrect_enc <= 1; end if (state == 1 && enclosure_count > 0) begin if (enclosure_count == 0) state <= 2; else if (enclosure_count == 1) state <= 2; else state <= 2; end end 2: begin if (incorrect_enc == 0) begin result_reg <= 2'b00; end else begin result_reg <= 2'b01; end done_reg <= 1; state <= 3; end 3: begin state <= 3; done_reg <= 1; end endcase end end assign result = result_reg; assign done = done_reg; endmodule